    config: TAccountMetas[1];
    plan: TAccountMetas[2];
    fundingMint: TAccountMetas[3];
    fundingTokenProgram: TAccountMetas[4];
    ownerFundingToken: TAccountMetas[5];
    staging: TAccountMetas[6];
    /** Receives the spent funding in the devnet build (never burned). */
    treasuryToken: TAccountMetas[7];
    /** Required when `config.protocol_fee_bps > 0`. */
    feeToken?: TAccountMetas[8] | undefined;
    subscriptionAuthority: TAccountMetas[9];
    recurringDelegation: TAccountMetas[10];
