export function parseExecuteInstallmentInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedExecuteInstallmentInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 13) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 13,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === OVELO_GUARD_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      keeper: getNextAccount(),
      config: getNextAccount(),
      plan: getNextAccount(),
      fundingMint: getNextAccount(),
      fundingTokenProgram: getNextAccount(),
      ownerFundingToken: getNextAccount(),
      staging: getNextAccount(),
      treasuryToken: getNextAccount(),
      feeToken: getNextOptionalAccount(),
      subscriptionAuthority: getNextAccount(),
      recurringDelegation: getNextAccount(),
      subscriptionsEventAuthority: getNextAccount(),
      subscriptionsProgram: getNextAccount(),
    },
    data: getExecuteInstallmentInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
